/** gen_preview's input (§5.18): a rectangle sampled every `step` tiles */
export interface PreviewRequest {
  x0: number;
  y0: number;
  /** samples */
  width: number;
  height: number;
  /** tiles per sample */
  step: number;
  flags: number;
}
export const PreviewRequestCodec = {
  /** The encoded size in bytes. */
  SIZE: 24,
  /** Byte offsets of the fields. */
  OFFSET: { x0: 0, y0: 4, width: 8, height: 12, step: 16, flags: 20 },
  /** A value with every field at its default. */
  defaults(): PreviewRequest {
    return { x0: 0, y0: 0, width: 0, height: 0, step: 0, flags: 0 };
  },
  /** Field reads at byte offset `o` of a DataView (no validation: for records already validated). */
  get: {
    x0: (v: DataView, o: number): number => v.getInt32(o + 0, true),
    y0: (v: DataView, o: number): number => v.getInt32(o + 4, true),
    width: (v: DataView, o: number): number => v.getUint32(o + 8, true),
    height: (v: DataView, o: number): number => v.getUint32(o + 12, true),
    step: (v: DataView, o: number): number => v.getUint32(o + 16, true),
    flags: (v: DataView, o: number): number => v.getUint32(o + 20, true),
  },
  read(r: Reader, _field?: string): PreviewRequest {
    
    const f_x0 = r.i32("PreviewRequest.x0");
    const f_y0 = r.i32("PreviewRequest.y0");
    const at_width = r.pos;
    const f_width = r.u32("PreviewRequest.width");
    if (f_width < 1 || f_width > 4096) throw r.errAt(at_width, 'range', "PreviewRequest.width");
    const at_height = r.pos;
    const f_height = r.u32("PreviewRequest.height");
    if (f_height < 1 || f_height > 4096) throw r.errAt(at_height, 'range', "PreviewRequest.height");
    const at_step = r.pos;
    const f_step = r.u32("PreviewRequest.step");
    if (f_step < 1 || f_step > 1024) throw r.errAt(at_step, 'range', "PreviewRequest.step");
    const f_flags = PreviewFlagsCodec.read(r, "PreviewRequest.flags");
    const v: PreviewRequest = { x0: f_x0, y0: f_y0, width: f_width, height: f_height, step: f_step, flags: f_flags };
    
    return v;
  },
  write(w: Writer, v: PreviewRequest, _field?: string): void {
    
    w.i32(v.x0, "PreviewRequest.x0");
    w.i32(v.y0, "PreviewRequest.y0");
    if (v.width < 1 || v.width > 4096) throw new EncodeError('range', "PreviewRequest.width");
    w.u32(v.width, "PreviewRequest.width");
    if (v.height < 1 || v.height > 4096) throw new EncodeError('range', "PreviewRequest.height");
    w.u32(v.height, "PreviewRequest.height");
    if (v.step < 1 || v.step > 1024) throw new EncodeError('range', "PreviewRequest.step");
    w.u32(v.step, "PreviewRequest.step");
    PreviewFlagsCodec.write(w, v.flags, "PreviewRequest.flags");
  },
  compare(a: PreviewRequest, b: PreviewRequest): number {
    { const c = cmpScalar(a.x0, b.x0); if (c !== 0) return c; }
    { const c = cmpScalar(a.y0, b.y0); if (c !== 0) return c; }
    { const c = cmpScalar(a.width, b.width); if (c !== 0) return c; }
    { const c = cmpScalar(a.height, b.height); if (c !== 0) return c; }
    { const c = cmpScalar(a.step, b.step); if (c !== 0) return c; }
    { const c = cmpScalar(a.flags, b.flags); if (c !== 0) return c; }
    return 0;
  },
  dump(d: Dump, v: PreviewRequest, prefix = ''): void {
    d.int(`${prefix}x0`, v.x0);
    d.int(`${prefix}y0`, v.y0);
    d.int(`${prefix}width`, v.width);
    d.int(`${prefix}height`, v.height);
    d.int(`${prefix}step`, v.step);
    d.int(`${prefix}flags`, v.flags);
  },
};

