/** sim_save's output: the sections at the current tick boundary (codec raw) and the lineage the save carries */
export interface SaveOutput {
  sections: SectionFrame[];
  r: bigint;
}
export const SaveOutputCodec = {
  /** The bytes before the first variable-length field. */
  PREFIX: 4,
  /** Byte offsets of the fields in the fixed prefix. */
  OFFSET: { section_count: 0 },
  /** A value with every field at its default (optional fields absent). */
  defaults(): SaveOutput {
    return { sections: [], r: 0n };
  },
  /** Field reads at byte offset `o` of a DataView (no validation: for records already validated). */
  get: {
    section_count: (v: DataView, o: number): number => v.getUint32(o + 0, true),
  },
  read(r: Reader): SaveOutput {
    
    const f_section_count = r.u32("SaveOutput.section_count");
    const f_sections = readN(r, f_section_count, 0, "SaveOutput.sections", () => SectionFrameCodec.read(r));
    const f_r = r.u64("SaveOutput.r");
    
    return { sections: f_sections, r: f_r };
  },
  write(w: Writer, v: SaveOutput): void {
    
    const f_section_count = v.sections.length;
    if (f_section_count > 4294967295) throw new EncodeError('bad_count', "SaveOutput.section_count");
    w.u32(f_section_count, "SaveOutput.section_count");
    for (const x of v.sections) { SectionFrameCodec.write(w, x); }
    w.u64(v.r, "SaveOutput.r");
    
  },
  /** Decodes one value that fills `bytes` exactly. */
  decode(bytes: Uint8Array): SaveOutput {
    const r = new Reader(bytes);
    const v = SaveOutputCodec.read(r);
    r.finish("SaveOutput");
    return v;
  },
  /** Encodes one value. */
  encode(v: SaveOutput): Uint8Array {
    const w = new Writer();
    SaveOutputCodec.write(w, v);
    return w.finish();
  },
  dump(d: Dump, v: SaveOutput, prefix = ''): void {
    d.int(`${`${prefix}sections`}.len`, v.sections.length); v.sections.forEach((x, i) => { SectionFrameCodec.dump(d, x, `${`${`${prefix}sections`}[${i}]`}.`); });
    d.int(`${prefix}r`, v.r);
  },
};

