/** The per-tick digest's record (§4.8): XXH64 (seed 0) of these bytes is d_t; never stored. C1b decisions: the RNG words are those of every stream the world holds (the RNG section's records, none in M0), in RngStream order; this tick's nonzero counters form two lists, production then consumption, each in ascending key; each list is preceded by its u32 count (§4.8 states the count only for the counters), so the record decodes unambiguously. The GLOBALS fields that state.yaml marks `digest: tick` follow research_progress, in declaration order (none in M0) */
export interface TickDigest {
  tick: number;
  /** XXH64 of the closure's bytes as applied; an empty closure hashes zero bytes */
  closure_hash: bigint;
  rng: RngWords[];
  entity_count: number;
  produced: StatCounter[];
  consumed: StatCounter[];
  players: PlayerDigest[];
  /** the current research, 0xFFFF none */
  research_tech: number;
  research_progress: number;
}
export const TickDigestCodec = {
  /** The bytes before the first variable-length field. */
  PREFIX: 16,
  /** Byte offsets of the fields in the fixed prefix. */
  OFFSET: { tick: 0, closure_hash: 4, rng_count: 12 },
  /** A value with every field at its default (optional fields absent). */
  defaults(): TickDigest {
    return { tick: 0, closure_hash: 0n, rng: [], entity_count: 0, produced: [], consumed: [], players: [], research_tech: 0, research_progress: 0 };
  },
  /** Field reads at byte offset `o` of a DataView (no validation: for records already validated). */
  get: {
    tick: (v: DataView, o: number): number => v.getUint32(o + 0, true),
    closure_hash: (v: DataView, o: number): bigint => v.getBigUint64(o + 4, true),
    rng_count: (v: DataView, o: number): number => v.getUint32(o + 12, true),
  },
  read(r: Reader): TickDigest {
    
    const f_tick = TickCodec.read(r, "TickDigest.tick");
    const f_closure_hash = r.u64("TickDigest.closure_hash");
    const f_rng_count = r.u32("TickDigest.rng_count");
    const f_rng = readN(r, f_rng_count, 16, "TickDigest.rng", () => RngWordsCodec.read(r, "TickDigest.rng"));
    const f_entity_count = r.u32("TickDigest.entity_count");
    const f_produced_count = r.u32("TickDigest.produced_count");
    const f_produced = readN(r, f_produced_count, 12, "TickDigest.produced", () => StatCounterCodec.read(r, "TickDigest.produced"));
    const f_consumed_count = r.u32("TickDigest.consumed_count");
    const f_consumed = readN(r, f_consumed_count, 12, "TickDigest.consumed", () => StatCounterCodec.read(r, "TickDigest.consumed"));
    const f_player_count = r.u32("TickDigest.player_count");
    const f_players = readN(r, f_player_count, 22, "TickDigest.players", () => PlayerDigestCodec.read(r, "TickDigest.players"));
    const f_research_tech = TechIdCodec.read(r, "TickDigest.research_tech");
    const f_research_progress = r.f64("TickDigest.research_progress");
    
    return { tick: f_tick, closure_hash: f_closure_hash, rng: f_rng, entity_count: f_entity_count, produced: f_produced, consumed: f_consumed, players: f_players, research_tech: f_research_tech, research_progress: f_research_progress };
  },
  write(w: Writer, v: TickDigest): void {
    
    const f_rng_count = v.rng.length;
    if (f_rng_count > 4294967295) throw new EncodeError('bad_count', "TickDigest.rng_count");
    const f_produced_count = v.produced.length;
    if (f_produced_count > 4294967295) throw new EncodeError('bad_count', "TickDigest.produced_count");
    const f_consumed_count = v.consumed.length;
    if (f_consumed_count > 4294967295) throw new EncodeError('bad_count', "TickDigest.consumed_count");
    const f_player_count = v.players.length;
    if (f_player_count > 4294967295) throw new EncodeError('bad_count', "TickDigest.player_count");
    TickCodec.write(w, v.tick, "TickDigest.tick");
    w.u64(v.closure_hash, "TickDigest.closure_hash");
    w.u32(f_rng_count, "TickDigest.rng_count");
    for (const x of v.rng) { RngWordsCodec.write(w, x, "TickDigest.rng"); }
    w.u32(v.entity_count, "TickDigest.entity_count");
    w.u32(f_produced_count, "TickDigest.produced_count");
    for (const x of v.produced) { StatCounterCodec.write(w, x, "TickDigest.produced"); }
    w.u32(f_consumed_count, "TickDigest.consumed_count");
    for (const x of v.consumed) { StatCounterCodec.write(w, x, "TickDigest.consumed"); }
    w.u32(f_player_count, "TickDigest.player_count");
    for (const x of v.players) { PlayerDigestCodec.write(w, x, "TickDigest.players"); }
    TechIdCodec.write(w, v.research_tech, "TickDigest.research_tech");
    w.f64(v.research_progress, "TickDigest.research_progress");
    
  },
  /** Decodes one value that fills `bytes` exactly. */
  decode(bytes: Uint8Array): TickDigest {
    const r = new Reader(bytes);
    const v = TickDigestCodec.read(r);
    r.finish("TickDigest");
    return v;
  },
  /** Encodes one value. */
  encode(v: TickDigest): Uint8Array {
    const w = new Writer();
    TickDigestCodec.write(w, v);
    return w.finish();
  },
  dump(d: Dump, v: TickDigest, prefix = ''): void {
    d.int(`${prefix}tick`, v.tick);
    d.int(`${prefix}closure_hash`, v.closure_hash);
    d.int(`${`${prefix}rng`}.len`, v.rng.length); v.rng.forEach((x, i) => { RngWordsCodec.dump(d, x, `${`${`${prefix}rng`}[${i}]`}.`); });
    d.int(`${prefix}entity_count`, v.entity_count);
    d.int(`${`${prefix}produced`}.len`, v.produced.length); v.produced.forEach((x, i) => { StatCounterCodec.dump(d, x, `${`${`${prefix}produced`}[${i}]`}.`); });
    d.int(`${`${prefix}consumed`}.len`, v.consumed.length); v.consumed.forEach((x, i) => { StatCounterCodec.dump(d, x, `${`${`${prefix}consumed`}[${i}]`}.`); });
    d.int(`${`${prefix}players`}.len`, v.players.length); v.players.forEach((x, i) => { PlayerDigestCodec.dump(d, x, `${`${`${prefix}players`}[${i}]`}.`); });
    d.int(`${prefix}research_tech`, v.research_tech);
    d.f64(`${prefix}research_progress`, v.research_progress);
  },
};

